<?php
$api=rtrim(getenv('MONITOR_API_URL')?:'http://api:3000','/');
function req($method,$path,$body=null){global $api;$ch=curl_init($api.$path);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CUSTOMREQUEST=>$method,CURLOPT_TIMEOUT=>8,CURLOPT_HTTPHEADER=>['Content-Type: application/json']]);if($body!==null)curl_setopt($ch,CURLOPT_POSTFIELDS,json_encode($body));$out=curl_exec($ch);curl_close($ch);return json_decode($out?:'{}',true)?:[];}
$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$action=$_POST['action']??'';if($action==='add-rule'){$msg='Rule management endpoint is ready; use API/admin integration to persist rules.';}}
